use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

fn run(path: &str) -> Result<String, String> {
    let source = fs::read_to_string(path)
        .map_err(|error| format!("cannot read '{}': {}", path, error))?;
    let mut order = Vec::new();
    let mut values = HashMap::new();

    for (line_index, raw_line) in source.lines().enumerate() {
        let line_number = line_index + 1;
        let line = raw_line.trim_end_matches('\r');
        let parts: Vec<&str> = line.split('|').collect();
        if parts.len() != 3 {
            return Err(format!("malformed record on line {}", line_number));
        }

        match parts[0] {
            "put" => {
                if parts[1].is_empty() {
                    return Err(format!("empty key on line {}", line_number));
                }
                if !values.contains_key(parts[1]) {
                    order.push(parts[1].to_string());
                }
                values.insert(parts[1].to_string(), parts[2].to_string());
            }
            "delete" => {
                if parts[1].is_empty() || !parts[2].is_empty() {
                    return Err(format!("malformed delete record on line {}", line_number));
                }
                if values.remove(parts[1]).is_some() {
                    order.retain(|key: &String| key != parts[1]);
                }
            }
            kind => return Err(format!("unknown record kind '{}' on line {}", kind, line_number)),
        }
    }

    let mut output = String::new();
    for key in order {
        if let Some(value) = values.get(&key) {
            output.push_str(&key);
            output.push('=');
            output.push_str(value);
            output.push('\n');
        }
    }
    Ok(output)
}

fn main() {
    let mut arguments = env::args();
    let _program = arguments.next();
    let path = match arguments.next() {
        Some(path) => path,
        None => {
            eprintln!("missing journal.log path");
            process::exit(1);
        }
    };

    match run(&path) {
        Ok(output) => print!("{}", output),
        Err(error) => {
            eprintln!("{}", error);
            process::exit(1);
        }
    }
}
